#!/usr/bin/env python3
"""Disjoint real ELF and source-exact admission manifest for initial native hook."""
import argparse,hashlib,json,re,shutil,subprocess
from pathlib import Path
R=Path(__file__).resolve().parents[1]
TC=Path('/scratch/eygao/iris-cy/.conda-env/riscv-tools/bin')
def sha(p):return hashlib.sha256(Path(p).read_bytes()).hexdigest()
def main():
 p=argparse.ArgumentParser(__doc__);p.add_argument('--output',type=Path,required=True);a=p.parse_args();out=a.output.resolve();out.mkdir(parents=True,exist_ok=False);shutil.copy2(Path(__file__),out/'builder.py');source=R/'timing/saturn_timing_live_guest.c';shutil.copy2(source,out/source.name);gcc=TC/'riscv64-unknown-elf-gcc';objdump=TC/'riscv64-unknown-elf-objdump';saturn=R/'third_party/saturn';bench=R/'benchmarks';elf=out/'guest.elf'
 cmd=[str(gcc),'-O2','-g','-Wall','-Wextra','-Werror','-ffreestanding','-fno-builtin','-fno-tree-vectorize','-fno-tree-slp-vectorize','-ffunction-sections','-fdata-sections','-fno-common','-mcmodel=medany','-mabi=lp64d','-march=rv64gcv_zicsr_zifencei','-nostdlib','-static','-Wl,--build-id=none,--gc-sections','-DIRIS_HARTS=3','-I'+str(bench),'-I'+str(saturn/'benchmarks/common'),'-T',str(bench/'link.ld'),str(bench/'start.S'),str(bench/'runtime.c'),str(source),'-lgcc','-o',str(elf)]
 with(out/'build.log').open('w')as log:subprocess.run(cmd,stdout=log,stderr=subprocess.STDOUT,check=True)
 dis=subprocess.check_output([str(objdump),'-d','-M','no-aliases',str(elf)],text=True);(out/'guest.disassembly').write_text(dis);admission=[];configuration=[];vectors=[]
 for line in dis.splitlines():
  m=re.match(r'^\s*([0-9a-f]+):\s+([0-9a-f]{8})\s+(.*)',line)
  if not m:continue
  pc,raw=int(m[1],16),int(m[2],16)
  if raw&0x7f not in[0x57,0x77]:continue
  row={'pc':pc,'instruction':raw,'hex':m[2],'disassembly':m[3]};vectors.append(row)
  if raw&0x7f==0x57 and(raw>>12)&7==7:configuration.append(row)
  else:admission.append(row)
 patterns=sorted({r['instruction']for r in admission});shuttle=R/'build/rtl-verilator/gen-collateral/ShuttleCore.sv';bank=R/'build/saturn-timing-component-v1-final/build/saturn-timing-source-v1/compute/rtl/RegisterFileBank.sv';pins={'chipyard':'b4542facf6cc9457f6e358e8f80a8b3a0ff5df19','saturn':'536774bd4c5e3bcd7813a4a0dc72fc87e5818532','rocket-chip':'fc745a8c377fdbf1d278eea81da9ac47b4b5fbc0','shuttle':'a536ed1df91a0f65770e36758291d02a8cb929c4'}
 manifest={'schema':'iris.saturn_initial_live_ELF_capability.v1','ELF_sha256':sha(elf),'harts':3,'compute_owner_harts':[0],'hart1_role':'scalar peer and barriers','hart2_role':'scalar producer and barriers; no VME','admitted_actual_unit_EX_patterns':[{'mask':0xffffffff,'value':raw}for raw in patterns],'actual_unit_EX_instructions':admission,'CPU_configuration_instructions_not_dispatched_to_unit':configuration,'all_vector_encodings':vectors,'initial_dynamic_source_inputs':{'vstart':0,'frm':0,'vxrm':0,'prv':3,'vector_unit_profiles':{'0':'Compute128','1':'Compute128 (idle)','2':'Rocket256 (idle)'},'RVV_probe':{'VL':1,'SEW':8,'LMUL':1,'vta':True,'vma':True},'matrix_compute':{'VL':32,'tm':32,'tk':1,'SEW':8,'vtwiden':3,'altfmt':0,'LMUL':1,'vta':True,'vma':True},'row_readout':{'VL':32,'SEW':32,'vtwiden':1,'altfmt':0,'LMUL':4,'vta':True,'vma':True,'TSS':0},'transport_rule':'Use real CPU EX vconfig and scalar operands, not these documented expectations as state injection.'},'drain_rule':'Real source CPU FENCE gate plus retained physical ownership; scalar retirement is not async completion. Native admission must reject unsupported pending interactions.','first_capability_refusals':['vector memory','shared FPU','column readout','interrupt while unit pending','uninitialized numeric operand','source write vs private oracle mismatch'],'expected_values':{'RVV':8,'matrix_first_row_element':6,'scalar_sum':64,'peer_values':[0x71,0x72,0x73]},'source_pins':pins,'source_evidence':{'Shuttle_fence_gate':{'path':str(shuttle),'sha256':sha(shuttle),'line':1513},'physical_VRF_write_priority':{'path':str(bank),'sha256':sha(bank),'line':93}},'executed_in_native_timing_model':False,'executed_on_FPGA':False,'timing_calibrated':False,'hardware_contacted':False};(out/'admission.json').write_text(json.dumps(manifest,indent=2)+'\n')
 inputs=[Path(__file__),source,gcc,objdump,saturn/'benchmarks/common/vme.h',*[bench/n for n in ['start.S','runtime.c','runtime.h','uart_drain.h','link.ld']],shuttle,bank];report={'schema':'iris.saturn_initial_live_ELF_build.v1','argv':cmd,'compiler_version':subprocess.check_output([str(gcc),'--version'],text=True).splitlines()[0],'input_sha256':{str(p):sha(p)for p in inputs},'source_pins':pins,'ELF_sha256':sha(elf),'admission_sha256':sha(out/'admission.json'),'disassembly_sha256':sha(out/'guest.disassembly'),'common_CRT_or_runtime_edited':False,'hardware_contacted':False};(out/'build.json').write_text(json.dumps(report,indent=2)+'\n');print(json.dumps({'ELF_sha256':report['ELF_sha256'],'admission_sha256':report['admission_sha256'],'actual_unit_patterns':len(patterns)}))
